    "content": "随着政策红利不断落地、住房消费需求持续释放，9月房地产市场延续回暖态势，重点城市二手房成交放量，“金九”表现亮眼。中指研究院数据显示，9月，二手房活跃度继续高位运行，重点20城二手房成交11.9万套，同比增长7.4%。今年前9个月，重点20城二手住宅成交111.8万套，同比增长6.4%。其中，北京、上海等城市二手房市场成交持续放量。9月，北京、上海二手房分别成交1.6万套、2.4万套，环比分别增长13.7%、3.3%。值得注意的是，上海9月二手房成交量同比增长17.2%，连续七个月同比增长。（证券时报）"
