    "description": "中新网云南昭通10月10日电 (时文枝 李嘉娴)第十一届云南省花灯滇剧艺术周9日晚在云南省昭通市启幕。即日起至10月15日，云南省专业花灯滇剧院团、民间传统艺人与省外戏曲名家将以戏曲为媒，陆续登台献艺、交流切磋，集中展现云南戏曲的传承活力与艺术风采，彰显“有一种叫云南的生活”的独特魅力。",
    "content": "中新网云南昭通10月10日电 (时文枝 李嘉娴)第十一届云南省花灯滇剧艺术周9日晚在云南省昭通市启幕。即日起至10月15日，云南省专业花灯滇剧院团、民间传统艺人与省外戏曲名家将以戏曲为媒，陆续登台献艺、交流切磋，集中展现云南戏曲的传承活力与艺术风采，彰显“有一种叫云南的生活”的独特魅力。"
