    "author": "",
    "description": "今年以来，券商债券融资继续升温。Wind数据显示，截至发稿，今年以来券商境内发债规模为1.68万亿元，同比增长28.24%。其中，国泰海通证券、中信证券、中信建投证券今年以来境内发债规模均已超千亿元。在业内人士看来，在市场交投活跃、重资本业务扩张的背景下，券商发债需求上升，同时低利率环境也为其压降融资成本提供了窗口。（中证报）",
