    "pub_date": "2026-10-10 09:26:35",
    "author": "",
    "description": "今天起，国内航线客票燃油附加费上调。调整后的标准为：成人旅客800公里及800公里以下航线每航段50元，800公里以上航线每航段90元，相较于调整前分别上涨10元和20元。婴儿旅客免收；儿童、革命伤残军人、因公致残人民警察按实际收取标准减半收取。此前销售的国内客票，如在今天及以后进行变更，不再按新标准补收燃油附加差价。（央视新闻）",
    "content": "今天起，国内航线客票燃油附加费上调。调整后的标准为：成人旅客800公里及800公里以下航线每航段50元，800公里以上航线每航段90元，相较于调整前分别上涨10元和20元。婴儿旅客免收；儿童、革命伤残军人、因公致残人民警察按实际收取标准减半收取。此前销售的国内客票，如在今天及以后进行变更，不再按新标准补收燃油附加差价。（央视新闻）"
