    "description": "自2026年7月1日以来，截至10月9日，拟增持金额上限及拟回购金额上限合计超过千亿元。整体来看，下半年以来约470股发起增持或回购计划，主要分布于机械设备、电力设备、电子、医药生物等行业。进一步统计显示，上述约470股中，拟增持金额不低于3亿元或拟回购金额不低于3亿元（保留增持、回购计划仍在进行的标的，剔除完成增持回购的个股），且最新市盈率低于所属行业市盈率的个股仅有13只。按照市盈率折价率排序，华新建材、山东路桥、中国建筑最新市盈率…",
    "content": "自2026年7月1日以来，截至10月9日，拟增持金额上限及拟回购金额上限合计超过千亿元。整体来看，下半年以来约470股发起增持或回购计划，主要分布于机械设备、电力设备、电子、医药生物等行业。进一步统计显示，上述约470股中，拟增持金额不低于3亿元或拟回购金额不低于3亿元（保留增持、回购计划仍在进行的标的，剔除完成增持回购的个股），且最新市盈率低于所属行业市盈率的个股仅有13只。按照市盈率折价率排序，华新建材、山东路桥、中国建筑最新市盈率较所属行业市盈率折价均超过40%。（证券时报）"
