    "description": "忙碌的日常里，总想寻找一点不一样的小滋味，避开甜腻的瓶装饮料，最近遇见百未草姜黄植物饮料，小小的一袋，藏着植物的自然风味。 这款饮品来自山东庆葆堂，30ml 一袋，一盒五份，轻盈的袋装，可以随手放进包中。不用准备水杯，不用等待冲泡，撕开袋口，就能品尝到调配好的植物饮品。配料选用姜黄搭配香水柠檬，姜黄素含量 200mg/100g，两种植物交织出独特的味道。 姜黄自带温润醇厚的底色，香水柠檬注入清爽气息，二者相融，褪去过重甜感，入口是柔和自…",
