    "link": "https://www.chinanews.com.cn/sh/2026/10-10/10710006.shtml",
    "pub_date": "2026-10-10 09:05:01",
    "author": "",
    "description": "中新网10月10日电 据中央气象台网站消息，中东部地区以多云或晴为主。昨日，强降雨主要出现在海南，其中海南东部部分地区出现暴雨或大暴雨。今天起，海南强降雨将告一段落。预计未来三天，我国中东部地区以多云或晴为主，青藏高原大部、西北地区东部、四川盆地、华北西部和南部等地有小到中雨或雨夹雪，其中四川、陕西局地有大雨或暴雨。",
