    "content": "新华社巴拿马城10月9日电（记者许咏政 李佳旭）据巴拿马大学地球科学研究所初步测定，9日中午强震后，巴拿马当天下午又发生6.9级地震。 此次6.9级地震发生于当地时间9日15时25分（北京时间10日4时25分），震中位于巴拿马西南部、科伊瓦岛东北约25公里处，震源深度5公里。 另据美国地质调查局地震信息网消息，此次地震为6.6级。 据美国上述机构消息，巴拿马上皮塔洛萨地区附近当地时间9日12时56分发生7.6级地震。巴拿马大学地球科学研究所将此次地震定级为7.2级。巴拿马首都巴拿马城震感明显。 强震后，巴拿马已记录…"
