    "content": "新华社伦敦10月9日电（记者赵阳）英国伦敦股市《金融时报》100种股票平均价格指数9日报收于10552.05点，较前一交易日上涨110.45点，涨幅为1.06%。欧洲三大股指当天全线上涨。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：出版集团励讯股价上涨4.82%，矿业公司安托法加斯塔股价上涨4.58%，软件公司赛奇股价上涨4.28%，资产管理企业中间资本集团股价上涨4.21%，市场征信服务商益博睿股价上涨4.20%。 当天伦敦股市成分股中位于跌幅前五位的个股分别为：电信运营商非洲电信公司股价下跌6.27%，沃…"
