    "author": "沙达提",
    "description": "新华社德黑兰10月9日电（记者沙达提）伊朗东南部锡斯坦-俾路支斯坦省扎黑丹市9日发生路边炸弹爆炸事件，造成一名警察死亡、多名警察受伤。 据伊朗塔斯尼姆通讯社9日报道，遇害警察当时正在该地区执行任务，其乘坐的警车遭到炸弹袭击。报道援引当地警方发言人的话称，这起袭击发生在扎黑丹市附近公路上，主要策划者试图逃跑时被击毙。 另据伊朗法尔斯通讯社9日报道称，事件中还有多名警务人员受伤。目前尚无任何个人或组织宣称对此次袭击事件负责。 伊朗锡斯坦-俾…",
    "content": "新华社德黑兰10月9日电（记者沙达提）伊朗东南部锡斯坦-俾路支斯坦省扎黑丹市9日发生路边炸弹爆炸事件，造成一名警察死亡、多名警察受伤。 据伊朗塔斯尼姆通讯社9日报道，遇害警察当时正在该地区执行任务，其乘坐的警车遭到炸弹袭击。报道援引当地警方发言人的话称，这起袭击发生在扎黑丹市附近公路上，主要策划者试图逃跑时被击毙。 另据伊朗法尔斯通讯社9日报道称，事件中还有多名警务人员受伤。目前尚无任何个人或组织宣称对此次袭击事件负责。 伊朗锡斯坦-俾路支斯坦省与巴基斯坦和阿富汗接壤。长期以来，该省跨境毒品走私活动猖獗，安全形势严…"
