    "content": "新华社北京10月9日电 当地时间10月9日，2026年联合国教科文组织女童和妇女教育奖颁奖仪式在法国巴黎举行。国家主席习近平夫人、联合国教科文组织促进女童和妇女教育特使彭丽媛向颁奖仪式发表视频致辞。 彭丽媛向来自摩洛哥和秘鲁的获奖机构致以热烈祝贺。她表示，女童和妇女教育水平是衡量人类文明进步的重要标尺。近年来，在联合国教科文组织大力倡导和国际社会共同努力下，全球女童和妇女教育事业取得令人欣喜的进展。 彭丽媛指出，中国一贯高度重视女童和妇女教育，积极同联合国教科文组织及有关各方开展务实合作，惠及多国广大女性。近年来，…"
