    "author": "高剑飞",
    "description": "新华社阿克拉10月9日电（记者高剑飞）加纳卫生部8日晚发布声明，宣布该国上西部省暴发黄热病疫情，3例确诊病例已死亡。 声明表示，卫生部门已启动国家和区域卫生应急行动中心，并部署快速反应小组到受影响社区，开展病例搜索、监测和风险沟通工作，同时准备本月在受影响区域开展应急疫苗接种。 此前一天，加纳卫生部长夸贝纳·阿坎多宣布，该国6月至9月间至少报告了450例黄热病疑似病例，其中3例已确诊。加纳政府已派国家快速反应小组赴报告疑似病例较多的上西…",
    "content": "新华社阿克拉10月9日电（记者高剑飞）加纳卫生部8日晚发布声明，宣布该国上西部省暴发黄热病疫情，3例确诊病例已死亡。 声明表示，卫生部门已启动国家和区域卫生应急行动中心，并部署快速反应小组到受影响社区，开展病例搜索、监测和风险沟通工作，同时准备本月在受影响区域开展应急疫苗接种。 此前一天，加纳卫生部长夸贝纳·阿坎多宣布，该国6月至9月间至少报告了450例黄热病疑似病例，其中3例已确诊。加纳政府已派国家快速反应小组赴报告疑似病例较多的上西部省。 黄热病是一种由黄热病毒引起的急性传染病，由蚊子叮咬传播，主要在非洲和拉丁…"
