    "content": "新华社华盛顿10月9日电（记者黄强 徐剑梅）美国国务卿鲁比奥9日发表声明，宣布对国际刑事法院实施制裁。 鲁比奥在声明中称，“美国总统特朗普绝不允许国际刑事法院起诉美国人”，美方将禁止与该法院进行交易，“切断其资源，并使其运作能力陷入瘫痪”。鲁比奥还称，美国不受国际刑事法院的管辖，美方“决心采取必要行动，彻底消除这一威胁。要么国际刑事法院停止其威胁行径，要么我们将终结该法院”。 美国国务院新闻发言人办公室当天发表声明称，截至目前，美国已对国际刑事法院17名相关人员实施制裁。 7月13日，美国国务院宣布发起一项由多个政…"
