    "content": "新华社北京10月9日电（记者谢希瑶、王聿昊）10月8日至9日，商务部部长王文涛在北京与欧盟委员会贸易和经济安全委员谢夫乔维奇共同主持召开中欧贸易投资磋商机制第二次例会并发表联合声明。双方进行了务实、富有成效的讨论，并形成成果共识清单。 清单围绕贸易和投资平衡、出口管制、知识产权、世贸组织改革等方面形成了16条具体成果共识。其中包括：双方将继续探讨在世贸组织规则框架下，降低部分商品关税的可能性；双方以符合世贸组织规则的方式就混动汽车贸易达成谅解；双方将继续电动汽车反补贴案企业价格承诺和复审相关程序；双方同意就欧盟外国…"
